const http=require('node:http');
const html='<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body,#root{margin:0;height:100%;}#root{display:flex;}</style></head><body><div id="root"></div><script src="/fixture.bundle"></script></body></html>';
http.createServer(async(req,res)=>{try{if(req.url==='/'){res.setHeader('Content-Type','text/html');res.end(html);return;}if(req.url.startsWith('/api')){res.writeHead(403);res.end('No API access in fixture');return;}const route=req.url==='/fixture.bundle'?'/.cache/share-preview.bundle?platform=web&dev=true&hot=false&lazy=false':req.url;const result=await fetch('http://127.0.0.1:8081'+route);res.writeHead(result.status,Object.fromEntries([...result.headers].filter(([name])=>!['transfer-encoding','content-encoding','content-length'].includes(name))));res.end(Buffer.from(await result.arrayBuffer()));}catch(e){res.writeHead(500);res.end(String(e.message));}}).listen(8915,'127.0.0.1',()=>console.log('Isolated Share preview on http://localhost:8915'));
